    data = input().split()

    if not data:
        return

    N = int(data[0])
    M = int(data[1])

    broken = set()
    idx = 2
    for _ in range(M):
        broken.add(int(data[idx]))
        idx += 1

    MOD = 1_000_000_007

    dp = [0] * (N + 1)
    dp[0] = 1

    for i in range(1, N + 1):
        if i in broken:
            dp[i] = 0
            continue

        ways = 0
        if i == 1:
            ways = dp[0]
        else:
            if i - 1 >= 0:
                ways = (ways + dp[i - 1]) % MOD
            if i - 2 >= 0:
                ways = (ways + dp[i - 2]) % MOD
        dp[i] = ways

    print(dp[N])

if __name__ == "__main__":
